def get_bool_ids_greater_than(probs, limit=0.5):
    probs = np.array(probs)
    dim_len = len(probs.shape)
    if dim_len > 1:
        result = []
        for p in probs:
            result.append(get_bool_ids_greater_than(p, limit))
        return result
    else:
        result = []
        for i, p in enumerate(probs):
            if p > limit:
                result.append(i)
        return result

def get_span(start_ids, end_ids):
    start_ids = sorted(start_ids)
    end_ids = sorted(end_ids)

    start_pointer = 0
    end_pointer = 0
    len_start = len(start_ids)
    len_end = len(end_ids)
    couple_dict = {}
    while start_pointer < len_start and end_pointer < len_end:
        if start_ids[start_pointer] == end_ids[end_pointer]:
            couple_dict[end_ids[end_pointer]] = start_ids[start_pointer]
            start_pointer += 1
            end_pointer += 1
            continue
        if start_ids[start_pointer] < end_ids[end_pointer]:
            couple_dict[end_ids[end_pointer]] = start_ids[start_pointer]
            start_pointer += 1
            continue
        if start_ids[start_pointer] > end_ids[end_pointer]:
            end_pointer += 1
            continue
    result = [(couple_dict[end], end) for end in couple_dict]
    result = set(result)
    return result

def get_span_ids(span_set, offset_mapping):
